insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_schedule','schedule','noun','a plan that shows the times and dates when things will happen','[{"senseId":"schedule_1","meaning":"a plan that shows the times and dates when things will happen","acceptedParaphrases":["plan of times and dates","timetable of when things will happen"],"masteryContexts":[{"contextId":"u7_21_schedule_meaning","text":"The interview schedule showed that Karim’s meeting would begin at half past ten.","meaning":"a plan showing the times of events","wrongMeanings":["a list of questions to be answered","a report on how well people performed","a contract between two companies"]},{"contextId":"u7_21_schedule_paraphrase","text":"The manager had a very busy schedule, so she could only see candidates for twenty minutes each.","meaning":"a plan that is full of planned activities","wrongMeanings":["a record that is full of mistakes","a room that is full of equipment","a team that is full of experienced workers"]}],"situationDistractors":["A girl wrote the start and end time of every lesson on a card and stuck it on her wall.","A manager sent staff a list showing who would work on each day of the week.","An organiser printed a sheet showing when each speaker would talk at the conference.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_21_schedule_gap_1","answer":"schedule","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_21_schedule_gap_2","answer":"schedule","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_21_schedule_gap_3","answer":"schedule","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["shedule","schedual","scedule","schedulle","shedual","skedule"],"masteryPassages":[{"passageId":"u7_21_schedule_passage_1","contextId":"u7_21_schedule_gap_1","text":"The college interviewed fifteen applicants in a single day. Each person was given a ____ with a time, a room number and the name of the panel, so that the corridors never became crowded.","answer":"schedule"},{"passageId":"u7_21_schedule_passage_2","contextId":"u7_21_schedule_gap_2","text":"Zoe tried to join the football club, the school choir and the science society, but she soon realised that her ____ was too full. She had no time left for homework or sleep.","answer":"schedule"}],"contextDependentParaphrases":[],"wrongParaphrases":["list of rules to be obeyed","short report about a past event","record of money that was spent"],"misleadingDistractors":["a list of rules that must be obeyed","a short report about a past event","a record of money that has been spent"],"teacherNote":"Noun: a plan that shows when things will happen (a busy schedule, a schedule for the day, on schedule). Boundary: a schedule lists times and dates; an agenda lists topics. The verb (to schedule a meeting) is a related use of the same word and is not taught as a separate item."}]'::jsonb,'[]'::jsonb,'["a busy schedule","behind schedule","a flexible schedule"]'::jsonb,'live'),
('vocab_expectation','expectation','noun','a belief that something will happen, or that someone should behave or achieve in a certain way','[{"senseId":"expectation_1","meaning":"a belief that something will happen, or that someone should behave or achieve in a certain way","acceptedParaphrases":["belief that something will happen","what someone thinks should be achieved"],"masteryContexts":[{"contextId":"u7_22_expectation_meaning","text":"There is an expectation that candidates will dress smartly for an interview.","meaning":"a belief that people should behave in a certain way","wrongMeanings":["a doubt that people will attend an event","a reward that people receive after an event","a rule that people write after an event"]},{"contextId":"u7_22_expectation_paraphrase","text":"The new employee’s performance was far above the manager’s expectation after only three weeks.","meaning":"what a person believed would happen","wrongMeanings":["what a person feared might go wrong","what a person had completed in the past","what a person was told to ignore"]}],"situationDistractors":["A manager told a new worker that she was sure he would be on time every day.","A teacher said that she believed her students would all pass the exam.","A father told his daughter that he hoped she would try her best in the interview.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_22_expectation_gap_1","answer":"expectation","wrong":["holiday","recipe","souvenir"]},{"contextId":"u7_22_expectation_gap_2","answer":"expectation","wrong":["umbrella","sandwich","carpet"]},{"contextId":"u7_22_expectation_gap_3","answer":"expectation","wrong":["staircase","bicycle","neighbour"]}],"spellingErrors":["expectaton","expectasion","expetation","expecation","expectashion","exspectation"],"wordFamilyForms":[{"form":"expectation","partOfSpeech":"noun","example":"The headteacher explained the school’s expectation about behaviour on the first day.","pedagogicallyUseful":true},{"form":"expect","partOfSpeech":"verb","example":"You can expect three or four questions about your experience in the interview.","pedagogicallyUseful":true,"altExample":"Candidates should expect to wait for a few minutes before the panel is ready."},{"form":"expected","partOfSpeech":"adjective","example":"The expected result was a pass, but she received a distinction.","pedagogicallyUseful":true,"altExample":"The interview lasted longer than expected, and several people had to wait."}],"masteryPassages":[{"passageId":"u7_22_expectation_passage_1","contextId":"u7_22_expectation_gap_1","text":"Before the first day of work, the manager told Ayesha exactly what he hoped from her: to arrive early, to ask questions and to finish her tasks. Ayesha was glad to know the ____ so clearly.","answer":"expectation"},{"passageId":"u7_22_expectation_passage_2","contextId":"u7_22_expectation_gap_2","text":"When the exam results arrived, Marcus was delighted. His marks were much higher than his teacher’s ____, and she congratulated him in front of the class.","answer":"expectation"}],"contextDependentParaphrases":[],"wrongParaphrases":["surprise nobody had planned","reward for finishing a task","doubt about whether a plan is wise"],"misleadingDistractors":["a surprise that nobody had planned","a reward for finishing a task","a doubt about whether a plan is wise"],"teacherNote":"Noun: a belief that something will happen, or that someone should reach a certain standard (high expectation, meet someone’s expectation, an expectation of). The singular is taught here; it is often plural in speech and writing (expectations). Boundary: an expectation is what you believe will happen or hope for, and it may or may not come true."}]'::jsonb,'["expect","expected"]'::jsonb,'["meet an expectation","high expectation","an expectation of"]'::jsonb,'live'),
('vocab_impress','impress','verb','to make someone feel admiration or respect because of what you say or do','[{"senseId":"impress_1","meaning":"to make someone feel admiration or respect because of what you say or do","acceptedParaphrases":["make someone admire you","win someone’s respect"],"masteryContexts":[{"contextId":"u7_23_impress_meaning","text":"A neat CV and a polite email can impress an employer before the interview even begins.","meaning":"to make someone admire or respect you","wrongMeanings":["to make someone forget you completely","to make someone feel sorry for you","to make someone angry with you"]},{"contextId":"u7_23_impress_paraphrase","text":"The young musician hoped to impress the judges with her skill and confidence.","meaning":"to win admiration by showing ability","wrongMeanings":["to hide her ability from the judges","to ask the judges for advice","to copy the style of the judges"]}],"situationDistractors":["A girl arrived ten minutes early and spoke clearly, so the panel remembered her well.","A boy built a small robot and the teacher said it was one of the best projects she had ever seen.","A young cook prepared a perfect meal and the head chef praised her warmly.","The bus stopped outside the school and the driver opened the doors.","A woman folded the map and put it in her bag.","The class waited in the corridor until the exam hall was ready."],"gapDistractors":[{"contextId":"u7_23_impress_gap_1","answer":"impress","wrong":["borrow","repair","forget"]},{"contextId":"u7_23_impress_gap_2","answer":"impress","wrong":["invent","decorate","translate"]},{"contextId":"u7_23_impress_gap_3","answer":"impress","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["impres","imprees","impresss","inpress","emprress","impreess"],"wordFamilyForms":[{"form":"impress","partOfSpeech":"verb","example":"A polite email can impress a busy manager.","pedagogicallyUseful":true},{"form":"impression","partOfSpeech":"noun","example":"A good first impression can make a long interview much easier.","pedagogicallyUseful":true,"altExample":"The manager formed a positive impression of the candidate within the first five minutes."},{"form":"impressive","partOfSpeech":"adjective","example":"Her CV was impressive, with three languages and two years of voluntary work.","pedagogicallyUseful":true,"altExample":"It was impressive how calmly she answered the most difficult question."}],"masteryPassages":[{"passageId":"u7_23_impress_passage_1","contextId":"u7_23_impress_gap_1","text":"Aisha was not the most experienced applicant. However, she had read about the company’s latest project, and her clear questions about it helped her to ____ the panel.","answer":"impress"},{"passageId":"u7_23_impress_passage_2","contextId":"u7_23_impress_gap_2","text":"Many young people try to ____ others by talking loudly or by using difficult words. Teachers and employers usually respect honesty and clear ideas more than a show of cleverness.","answer":"impress"}],"contextDependentParaphrases":[],"wrongParaphrases":["to make someone bored","to give someone a reward","to ask someone to repeat"],"misleadingDistractors":["to make someone feel bored or tired","to give someone a gift or reward","to ask someone to repeat an answer"],"teacherNote":"Verb: to make someone feel admiration or respect because of what you say or do (impress the interviewer, impress someone with). Boundary: impress is about a positive effect on another person; it is not the same as persuade, which is about changing a decision. Related forms (impression, impressive) are taught in the Word Family pathway."}]'::jsonb,'["impression","impressive"]'::jsonb,'["impress an employer","hope to impress","impress with"]'::jsonb,'live'),
('vocab_respond_7','respond','verb','to give an answer or reaction, in speech or in writing, to a question or a message','[{"senseId":"respond_7_1","meaning":"to give an answer or reaction, in speech or in writing, to a question or a message","acceptedParaphrases":["give an answer to","answer in speech or writing"],"masteryContexts":[{"contextId":"u7_24_respond_7_meaning","text":"In the interview, Hana took a moment before she began to respond to the difficult question.","meaning":"to give an answer to a question","wrongMeanings":["to ask a different question in return","to look away from the person speaking","to write down the question for later"]},{"contextId":"u7_24_respond_7_paraphrase","text":"If an employer sends you an email, you should respond within a day or two.","meaning":"to give an answer to a message","wrongMeanings":["to delete a message without reading it","to send a message to many people","to wait for a second message to arrive"]}],"situationDistractors":["A student wrote back to the company the same day to accept the invitation to the interview.","A candidate listened to the whole question and then gave a clear answer.","A manager replied to every email she received before the end of the afternoon.","The librarian stamped each book and put it on the trolley.","A boy tied his shoelaces and then ran to catch the school bus.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_24_respond_7_gap_1","answer":"respond","wrong":["borrow","repair","forget"]},{"contextId":"u7_24_respond_7_gap_2","answer":"respond","wrong":["invent","decorate","translate"]},{"contextId":"u7_24_respond_7_gap_3","answer":"respond","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["responed","respnd","resbond","respund","resspond","respont"],"wordFamilyForms":[{"form":"respond","partOfSpeech":"verb","example":"Please respond to the invitation by the end of the week.","pedagogicallyUseful":true},{"form":"response","partOfSpeech":"noun","example":"The company was delighted with the response to its job advertisement.","pedagogicallyUseful":true,"altExample":"The panel was pleased with her thoughtful response to the final question."},{"form":"responsive","partOfSpeech":"adjective","example":"A responsive manager answers questions quickly and listens to what staff say.","pedagogicallyUseful":true,"altExample":"The helpline is very responsive and replies to messages within an hour."}],"masteryPassages":[{"passageId":"u7_24_respond_7_passage_1","contextId":"u7_24_respond_7_gap_1","text":"The email from the company asked Jamal to confirm that he would attend the interview. He knew that it was polite to ____ quickly, so he replied before the end of the same day.","answer":"respond"},{"passageId":"u7_24_respond_7_passage_2","contextId":"u7_24_respond_7_gap_2","text":"Interviewers sometimes ask unexpected questions to see how calmly a candidate can think. The best candidates do not panic. They take a breath and ____ in a clear, organised way.","answer":"respond"}],"contextDependentParaphrases":[],"wrongParaphrases":["to ask without waiting for an answer","to forget after reading","to read aloud to a group"],"misleadingDistractors":["to ask a question without waiting for an answer","to forget a message after reading it","to read a message aloud to a group"],"teacherNote":"Unit 7 item (respond_7), separate from the Unit 6 respond item; it shares only the lexical spelling list. Sense in this unit: to give an answer or a reaction to a question, an email or an application (respond to). It is followed by to. Boundary: respond is the general word for replying; answer is usually used for questions and tests."}]'::jsonb,'["response","responsive"]'::jsonb,'["respond to a question","respond to an email","respond quickly"]'::jsonb,'live'),
('vocab_relevant_7','relevant','adjective','connected with what is being discussed, so that it is useful or important for the purpose','[{"senseId":"relevant_7_1","meaning":"connected with what is being discussed, so that it is useful or important for the purpose","acceptedParaphrases":["connected to the subject","useful for what is being discussed"],"masteryContexts":[{"contextId":"u7_25_relevant_7_meaning","text":"Her work experience was relevant to the post because she had already managed a small team.","meaning":"closely connected with the purpose","wrongMeanings":["completely different from the purpose","slightly better than the purpose","much older than the purpose"]},{"contextId":"u7_25_relevant_7_paraphrase","text":"The interviewer asked her to keep her answers short and relevant.","meaning":"connected with the question and useful for it","wrongMeanings":["full of long and detailed stories","written in formal and polite words","spoken in a quiet and nervous voice"]}],"situationDistractors":["A girl applying to be a nurse mentioned her first-aid course and her voluntary work at a hospital.","A boy kept his answer to the question about teamwork and did not talk about his holidays.","A man listed only the jobs that were related to the post when he wrote his CV.","The bus stopped outside the school and the driver opened the doors.","A woman folded the map and put it in her bag.","The class waited in the corridor until the exam hall was ready."],"gapDistractors":[{"contextId":"u7_25_relevant_7_gap_1","answer":"relevant","wrong":["frozen","rectangular","wooden"]},{"contextId":"u7_25_relevant_7_gap_2","answer":"relevant","wrong":["enormous","furious","distant"]},{"contextId":"u7_25_relevant_7_gap_3","answer":"relevant","wrong":["bitter","crowded","careless"]}],"spellingErrors":["relevent","relavant","revelant","relevat","relivant","relevaant"],"wordFamilyForms":[{"form":"relevant","partOfSpeech":"adjective","example":"Choose examples that are relevant to the job you want.","pedagogicallyUseful":true},{"form":"relevance","partOfSpeech":"noun","example":"The relevance of her work experience was obvious to the panel.","pedagogicallyUseful":true,"altExample":"The teacher asked the class to explain the relevance of the example to the main argument."},{"form":"irrelevant","partOfSpeech":"adjective","example":"The detail about his holiday was irrelevant to the question about teamwork.","pedagogicallyUseful":true,"altExample":"Delete anything irrelevant from your CV so that the page is clear and short."}],"masteryPassages":[{"passageId":"u7_25_relevant_7_passage_1","contextId":"u7_25_relevant_7_gap_1","text":"Laila had worked in a swimming pool, a bakery and a bookshop. For her application to become a teaching assistant, she chose to describe only her ____ experience, which was the afternoons she had spent helping at a nursery.","answer":"relevant"},{"passageId":"u7_25_relevant_7_passage_2","contextId":"u7_25_relevant_7_gap_2","text":"The interviewer asked about teamwork, but Idris began to talk about his favourite football club. The panel listened politely, but his story was not ____ to the question.","answer":"relevant"}],"contextDependentParaphrases":[],"wrongParaphrases":["showing respect for someone","happening very often","difficult because it is long"],"misleadingDistractors":["showing great respect for someone","happening very often in a short time","difficult to understand because it is long"],"teacherNote":"Unit 7 item (relevant_7), separate from the Unit 2 relevant item; it shares only the lexical spelling list. Sense in this unit: connected with what is being discussed, so useful for the purpose, such as an example that matches the job (relevant to). Boundary: relevant is about connection to a purpose; it is not the same as important, because a fact can be important but not relevant to the question."}]'::jsonb,'["relevance","irrelevant"]'::jsonb,'["relevant experience","relevant to the question","highly relevant"]'::jsonb,'live'),
('vocab_contribute','contribute','verb','to give ideas, time, money or effort to help achieve something with other people','[{"senseId":"contribute_1","meaning":"to give ideas, time, money or effort to help achieve something with other people","acceptedParaphrases":["give ideas or effort to help","add to what a group is doing"],"masteryContexts":[{"contextId":"u7_26_contribute_meaning","text":"Quiet students sometimes find it difficult to contribute to a fast group discussion.","meaning":"to give ideas to help a group","wrongMeanings":["to listen without saying anything at all","to leave the group early","to choose the leader of the group"]},{"contextId":"u7_26_contribute_paraphrase","text":"Several local companies contribute money to the school’s sports programme every year.","meaning":"to give money to help something","wrongMeanings":["to take money from something","to refuse money for something","to borrow money for something"]}],"situationDistractors":["A boy listened for a while and then suggested a new way of dividing the work in the group.","A woman gave part of her salary to help build a new library in the town.","A student stayed after the lesson to help the teacher put the chairs away.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_26_contribute_gap_1","answer":"contribute","wrong":["borrow","repair","forget"]},{"contextId":"u7_26_contribute_gap_2","answer":"contribute","wrong":["invent","decorate","translate"]},{"contextId":"u7_26_contribute_gap_3","answer":"contribute","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["contribut","contribbute","contrybute","contributte","kontribute","contributt"],"wordFamilyForms":[{"form":"contribute","partOfSpeech":"verb","example":"Every member of the team can contribute something useful.","pedagogicallyUseful":true},{"form":"contribution","partOfSpeech":"noun","example":"Her contribution to the discussion helped the group to reach a decision.","pedagogicallyUseful":true,"altExample":"The headteacher thanked the students for their contribution to the charity event."},{"form":"contributor","partOfSpeech":"noun","example":"The main contributor to the school magazine is a student in Year 10.","pedagogicallyUseful":true,"altExample":"Each contributor to the project was invited to the final celebration."}],"masteryPassages":[{"passageId":"u7_26_contribute_passage_1","contextId":"u7_26_contribute_gap_1","text":"In the group interview, the assessors were not only listening for good ideas. They were also checking whether each person could ____ without interrupting and could build on what others had said.","answer":"contribute"},{"passageId":"u7_26_contribute_passage_2","contextId":"u7_26_contribute_gap_2","text":"The school asked parents to help pay for the new playground. Some parents were able to ____ money, while others gave a few hours of their time to paint the fence.","answer":"contribute"}],"contextDependentParaphrases":[],"wrongParaphrases":["to take from a group","to stop others joining in","to report a problem"],"misleadingDistractors":["to take something from a group","to prevent others from taking part","to report a problem to a manager"],"teacherNote":"Verb: to give ideas, time, money or effort to help with something that other people are also doing (contribute to a discussion, contribute ideas). It is usually followed by to or by an object such as ideas. Boundary: contribute means to give; take part means only to be there. The noun and the person noun are taught in the Word Family pathway."}]'::jsonb,'["contribution","contributor"]'::jsonb,'["contribute ideas","contribute to a discussion","contribute time and money"]'::jsonb,'live'),
('vocab_coherent','coherent','adjective','logical, clear and well organised, so that the parts fit together and are easy to follow','[{"senseId":"coherent_1","meaning":"logical, clear and well organised, so that the parts fit together and are easy to follow","acceptedParaphrases":["clear and logical","with parts that fit together well"],"masteryContexts":[{"contextId":"u7_27_coherent_meaning","text":"The candidate gave a coherent answer that moved clearly from the problem to the solution.","meaning":"logical and well organised","wrongMeanings":["full of long and difficult words","filled with jokes and stories","spoken far too quietly to hear"]},{"contextId":"u7_27_coherent_paraphrase","text":"The speech was not coherent because the speaker jumped from one idea to another without any link.","meaning":"clear because the ideas are connected","wrongMeanings":["short because the ideas are few","loud because the speaker is excited","formal because the words are polite"]}],"situationDistractors":["A girl explained her plan in three clear steps, and each step led naturally to the next.","A student wrote an essay in which every paragraph built on the one before it.","A candidate answered the question by giving a reason, an example and a short conclusion.","The librarian stamped each book and put it on the trolley.","A boy tied his shoelaces and then ran to catch the school bus.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_27_coherent_gap_1","answer":"coherent","wrong":["frozen","rectangular","wooden"]},{"contextId":"u7_27_coherent_gap_2","answer":"coherent","wrong":["enormous","furious","distant"]},{"contextId":"u7_27_coherent_gap_3","answer":"coherent","wrong":["bitter","crowded","careless"]}],"spellingErrors":["cohearent","coherant","cohirent","cohereent","coheerent","koherent"],"wordFamilyForms":[{"form":"coherent","partOfSpeech":"adjective","example":"A coherent plan makes it easier for everyone in the team to know what to do.","pedagogicallyUseful":true},{"form":"coherence","partOfSpeech":"noun","example":"The examiner praised the coherence of the whole essay.","pedagogicallyUseful":true,"altExample":"The lack of coherence in the speech made it difficult for the audience to understand the main message."},{"form":"coherently","partOfSpeech":"adverb","example":"She spoke coherently, even though the question was unexpected.","pedagogicallyUseful":true,"altExample":"Students who plan their ideas first can write more coherently under time pressure."}],"masteryPassages":[{"passageId":"u7_27_coherent_passage_1","contextId":"u7_27_coherent_gap_1","text":"The first candidate changed the subject three times in one answer and forgot the question. The second candidate gave a ____ reply that began with a reason and ended with an example, and the panel found it easy to follow.","answer":"coherent"},{"passageId":"u7_27_coherent_passage_2","contextId":"u7_27_coherent_gap_2","text":"Teachers often advise students to plan before they write. A short plan helps you to produce a ____ essay in which every paragraph links to the one before it.","answer":"coherent"}],"contextDependentParaphrases":[],"wrongParaphrases":["full of exciting new ideas","written very quickly","spoken in a quiet voice"],"misleadingDistractors":["full of exciting and unusual ideas","written very quickly and without care","spoken only in a quiet voice"],"teacherNote":"Adjective: logical, clear and well organised, so that the ideas fit together and are easy to follow (a coherent answer, a coherent argument). Boundary: coherent is about organisation and clear connection; it is not about length or about correct grammar alone. It is used for speech, writing and plans."}]'::jsonb,'["coherence","coherently"]'::jsonb,'["a coherent answer","a coherent argument","a clear and coherent plan"]'::jsonb,'live'),
('vocab_implication','implication','noun','a possible effect or meaning that is suggested but not stated directly','[{"senseId":"implication_1","meaning":"a possible effect or meaning that is suggested but not stated directly","acceptedParaphrases":["possible result that is not stated","meaning that is suggested indirectly"],"masteryContexts":[{"contextId":"u7_28_implication_meaning","text":"The implication of her answer was that she did not enjoy working in a team.","meaning":"a meaning that is suggested but not stated","wrongMeanings":["a reason that is given at the start","a question that is asked at the end","a rule that is written in the contract"]},{"contextId":"u7_28_implication_paraphrase","text":"The report discussed the main implication for students if the school day became an hour longer.","meaning":"the possible effects of a change","wrongMeanings":["the records of a change","the cost of a change","the dates of a change"]}],"situationDistractors":["A manager said that she was surprised the report was still unfinished, and the staff understood that she was displeased.","A teacher explained what would happen to the timetable if the new lesson was added.","A student noticed that the speaker had not said it directly but clearly thought the plan was weak.","The cleaner locked the office and switched off all the lights.","Two students carried a heavy box of books up the stairs.","The receptionist watered the plants beside the main entrance."],"gapDistractors":[{"contextId":"u7_28_implication_gap_1","answer":"implication","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_28_implication_gap_2","answer":"implication","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_28_implication_gap_3","answer":"implication","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["implicaton","implikation","implicasion","impliction","implecation","implicashion"],"masteryPassages":[{"passageId":"u7_28_implication_passage_1","contextId":"u7_28_implication_gap_1","text":"The manager did not say that the work was poor. She only said that she had expected more, but the ____ was clear to everyone in the room: the team would have to do better.","answer":"implication"},{"passageId":"u7_28_implication_passage_2","contextId":"u7_28_implication_gap_2","text":"Before the school decided to start lessons at eight o’clock, a committee studied the ____ for students who live far away. They found that many would have to leave home before sunrise.","answer":"implication"}],"contextDependentParaphrases":[],"wrongParaphrases":["clear instruction to be followed","mistake in a long document","reason for ending a talk"],"misleadingDistractors":["a clear instruction that must be followed","a mistake found in a long document","a reason for ending a conversation"],"teacherNote":"Noun: a possible effect or meaning that is suggested but not stated directly (the implication of, an implication for). It is often followed by of or for, and it is usually used about the effect of something on a person or plan. Boundary: an implication is not stated in the words, so it has to be worked out by the reader or listener."}]'::jsonb,'[]'::jsonb,'["the implication of","a serious implication","consider the implication"]'::jsonb,'live'),
('vocab_register','register','noun','the level of formality of the language that you use, such as formal or informal','[{"senseId":"register_1","meaning":"the level of formality of the language that you use, such as formal or informal","acceptedParaphrases":["level of politeness in your language","style of speaking or writing for a situation"],"masteryContexts":[{"contextId":"u7_29_register_meaning","text":"A student should change register when she moves from chatting with friends to writing an email to a head teacher.","meaning":"the level of formality in language","wrongMeanings":["the volume of a person’s voice","the speed of a person’s speech","the accent of a person’s speech"]},{"contextId":"u7_29_register_paraphrase","text":"The letter was written in a very formal register, with long sentences and polite phrases.","meaning":"a style of language suited to the situation","wrongMeanings":["a list of names kept by a school","a record of attendance at a class","a fee paid to take a test"]}],"situationDistractors":["A girl wrote “Dear Mr Hassan” and used polite phrases in her email to a head teacher.","A boy texted his cousin using short words and laughing emojis.","A woman changed from friendly language to a more professional style as soon as the interview began.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_29_register_gap_1","answer":"register","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_29_register_gap_2","answer":"register","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_29_register_gap_3","answer":"register","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["regester","regiester","registar","regisster","registor","rejister"],"masteryPassages":[{"passageId":"u7_29_register_passage_1","contextId":"u7_29_register_gap_1","text":"Zara used slang with her friends all the time, but in the interview she spoke more carefully, with full sentences and polite phrases. The panel noticed that she could change her ____ to suit the situation.","answer":"register"},{"passageId":"u7_29_register_passage_2","contextId":"u7_29_register_gap_2","text":"An email to a close friend can be short and relaxed. An email to a company needs a more formal ____, with a proper greeting and full sentences.","answer":"register"}],"contextDependentParaphrases":[],"wrongParaphrases":["official list of names","sudden change of voice","record of attendance"],"misleadingDistractors":["an official list of names","a loud and sudden change of voice","a record of attendance at a lesson"],"teacherNote":"Taught in its language sense only: the level of formality of the language you use (a formal register, an informal register, change register). The other meanings (an official list of names; the verb to register for something) are separate and are not taught here. Boundary: register is about how formal or informal the words and grammar are, not about how loud a person speaks."}]'::jsonb,'[]'::jsonb,'["a formal register","an informal register","change register"]'::jsonb,'live'),
('vocab_format','format','noun','the way in which something is arranged, organised or presented','[{"senseId":"format_1","meaning":"the way in which something is arranged, organised or presented","acceptedParaphrases":["way something is arranged","plan for how something is organised"],"masteryContexts":[{"contextId":"u7_30_format_meaning","text":"The college changed the format of the entrance test, so it now has two short papers instead of one long paper.","meaning":"the way something is organised","wrongMeanings":["the price of something","the result of something","the length of a break in something"]},{"contextId":"u7_30_format_paraphrase","text":"Candidates must send their CVs in the same format, so the panel can compare them easily.","meaning":"a set pattern for presenting information","wrongMeanings":["a private opinion about information","a long delay in sending information","a mistake in the information given"]}],"situationDistractors":["The leaflet said that the exam would have two papers, with multiple choice in the first and an essay in the second.","A teacher gave students a template with headings so that all the reports looked the same.","The organiser explained that the day would begin with talks and end with workshops.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_30_format_gap_1","answer":"format","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_30_format_gap_2","answer":"format","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_30_format_gap_3","answer":"format","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["formatt","fomat","formet","phormat","formmat","fourmat"],"masteryPassages":[{"passageId":"u7_30_format_passage_1","contextId":"u7_30_format_gap_1","text":"Before the speaking test, the teacher explained how it would work: a short warm-up, a talk on one topic and a discussion with the examiner. Knowing the ____ made the students feel less nervous.","answer":"format"},{"passageId":"u7_30_format_passage_2","contextId":"u7_30_format_gap_2","text":"The company asked all applicants to follow the same ____ for their CVs, with the same headings in the same order. This made it easy to compare the details quickly.","answer":"format"}],"contextDependentParaphrases":[],"wrongParaphrases":["short break between parts","list of rules about behaviour","mistake in the first part"],"misleadingDistractors":["a short break between two parts of an event","a list of rules about behaviour","a mistake made in the first part of a plan"],"teacherNote":"Noun: the way in which something is arranged, organised or presented (the format of a test, a document, an interview). It is often followed by of. Boundary: format is about the pattern or arrangement, whereas content is what is inside it. The verb to format a document and the computer sense are not taught here."}]'::jsonb,'[]'::jsonb,'["the format of the test","a standard format","change the format"]'::jsonb,'live')
